pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for large bin residual
    if bin_residual > bin_capacity / 2 {
        score += (bin_residual - bin_capacity / 2) as f64 * 1.5;
    }

    // Reward for fitting bins
    if fitting_bins_count > 0 {
        score -= item_size as f64 * 0.2;
    }

    // Bonus for open bins
    if open_bins_count == 0 {
        score += (bin_capacity - bin_residual) as f64 / bin_capacity * 8.0;
    } else {
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity * 2.5;
    }

    // Reward for mean residual
    if mean_residual > post_residual as f64 {
        score += (mean_residual - post_residual as f64) * 3.0;
    } else {
        score -= (post_residual as f64 - mean_residual) * 1.5;
    }

    // Bonus for large next item size
    if next_item_size > 75 {
        score += next_item_size as f64 / 25.0;
    }

    // Penalty for single fitting bin with residual less than next item size
    if fitting_bins_count == 1 && post_residual >= next_item_size {
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity * 3.0;
    } else if fitting_bins_count > 1 && post_residual >= next_item_size / 2 {
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity * 2.5;
    }

    // Reward for small bin residual
    if bin_residual < bin_capacity / 30 {
        score += (bin_capacity - bin_residual) as f64 / bin_capacity * 4.0;
    } else {
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity * 1.0;
    }

    // Bonus for small post residual
    if post_residual < 12 {
        score += 30.0;
    }
    if post_residual < 8 {
        score -= post_residual as f64 * 10.0;
    }

    // Lookahead trade-off: penalize bins that are too full for next item
    if bin_capacity - bin_residual <= next_item_size {
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize for not fitting all bins
    score -= (open_bins_count - fitting_bins_count) as f64 * 1.75;

    // Penalize if bin residual is large
    if bin_residual > bin_capacity / 3 {
        score -= (bin_residual - bin_capacity / 3) as f64 * 0.85;
    }

    // Bonus for fitting the next item precisely
    if fitting_bins_count == 1 && post_residual >= next_item_size {
        score += (next_item_size as f64 / 12.0);
    } else if fitting_bins_count > 1 && post_residual >= next_item_size / 3 {
        score += (next_item_size as f64 / 30.0);
    }

    // Penalize for open bins
    if open_bins_count > 0 {
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity * 2.0;
    } else {
        score += (bin_capacity - bin_residual) as f64 / bin_capacity * 4.0;
    }

    // Penalize if mean residual is higher than post residual
    if mean_residual < post_residual as f64 {
        score -= (post_residual as f64 - mean_residual) * 1.5;
    } else {
        score += (mean_residual - post_residual as f64) * 3.0;
    }

    // Penalize large next items
    if next_item_size > 150 {
        score -= next_item_size as f64 / 40.0;
    }

    // Bonus for small bin residuals
    if bin_residual < bin_capacity / 75 {
        score += (bin_capacity - bin_residual) as f64 / bin_capacity * 3.5;
    } else {
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity * 1.5;
    }

    // Bonus for low post residual
    if post_residual < 7 {
        score += 28.0;
    }

    // Penalize very low post residual
    if post_residual < 3 {
        score -= post_residual as f64 * 25.0;
    }

    // Adjust scores based on step index and total items
    if step_index % 3 == 0 {
        score *= 1.10;
    } else if step_index % 3 == 2 {
        score *= 0.90;
    }

    if total_items < 150 {
        score *= 1.15;
    } else if total_items > 700 {
        score *= 0.85;
    }

    // Final score adjustment
    let score = score * 0.75 + ((post_residual as f64) as f64) * 0.25;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize post_residual if it is too small (unusable dead space)
    if post_residual < 10 {
        score -= post_residual as f64 * 10.0; // Large penalty for very small gaps
    }

    // Pressure to use open bins by penalizing the score based on the number of available bins
    score -= (open_bins_count - fitting_bins_count) as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
