    if next_item_size > 100 {
        score -= next_item_size as f64 / 35.0;
    }

    // Bonus for small bin residuals
    if bin_residual < bin_capacity / 50 {
        score += (bin_capacity - bin_residual) as f64 / bin_capacity * 3.0;
    } else {
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity * 1.2;
    }

    // Bonus for low post residual
    if post_residual < 5 {
        score += 25.0;
