        score *= 0.95;
    }

    if total_items < 100 {
        score *= 1.1;
    } else if total_items > 500 {
        score *= 0.9;
    }

    // Final score adjustment
    let score = score * 0.70 + ((post_residual as f64) as f64) * 0.30;
    score
