pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize creating bins with excessive residual space
    if bin_residual > bin_capacity / 3 {
        score += (bin_residual - bin_capacity / 3) as f64 * 1.5;
    }

    // Reward fitting items into existing bins
    if fitting_bins_count > 0 {
        score -= item_size as f64 * 0.2;
    }

    // Penalize opening new bins
    if open_bins_count == 0 {
        score += (bin_capacity - bin_residual) as f64 / bin_capacity * 7.5;
    } else {
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity * 1.5;
    }

    // Reward bins with smaller residuals
    if mean_residual > post_residual as f64 {
        score += (mean_residual - post_residual as f64) * 2.5;
    } else {
        score -= (post_residual as f64 - mean_residual) * 1.25;
    }

    // Penalize large lookahead items
    if next_item_size > 50 {
        score += next_item_size as f64 / 15.0;
    }

    // Reward bins that can fit the next item
    if fitting_bins_count == 1 && post_residual >= next_item_size {
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity * 2.5;
    } else if fitting_bins_count > 1 && post_residual >= next_item_size / 3 {
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity * 1.75;
    }

    // Penalize bins with small capacity utilization
    if bin_residual < bin_capacity / 20 {
        score += (bin_capacity - bin_residual) as f64 / bin_capacity * 3.5;
    } else {
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity * 0.75;
    }

    // Reward bins that are likely to be close to full
    if post_residual < 15 {
        score += 25.0;
    }

    score
}
